<?php $errors = $errors ?? []; $selectedRole = old('role', $default_role ?? ''); ?><section class="auth-card"><div class="eyebrow">عضویت در جامعه</div><h1>حساب کاربری بسازید</h1><p class="muted">آینده‌ی حرفه‌ای خود را از همین امروز بسازید.</p><?php if ($errors): ?><div class="alert error">لطفاً موارد مشخص‌شده را بررسی کنید.</div><?php endif; ?><form method="post" action="<?= url('/register') ?>"><?= csrf_field() ?><fieldset><legend>می‌خواهم...</legend><div class="role-grid"><label class="role"><input type="radio" name="role" value="freelancer" required <?= $selectedRole === 'freelancer' ? 'checked' : '' ?>><strong>کار پیدا کنم</strong><small>فریلنسر هستم</small></label><label class="role"><input type="radio" name="role" value="employer" <?= $selectedRole === 'employer' ? 'checked' : '' ?>><strong>متخصص استخدام کنم</strong><small>کارفرما هستم</small></label></div></fieldset><label>ایمیل<input type="email" name="email" value="<?= old('email') ?>" required><?= isset($errors['email']) ? '<small class="field-error">'.e($errors['email']).'</small>' : '' ?></label><label>کشور<input type="text" name="country" value="<?= old('country') ?>" required autocomplete="country-name"></label><div class="form-row"><label>رمز عبور<input type="password" name="password" required minlength="12"></label><label>تکرار رمز عبور<input type="password" name="password_confirmation" required minlength="12"></label></div><label class="check"><input type="checkbox" name="terms" required> قوانین استفاده و حریم خصوصی را می‌پذیرم</label><button class="button full" type="submit">ساخت حساب <span>↗</span></button></form><p class="form-footer">قبلاً عضو شده‌اید؟ <a href="<?= url('/login') ?>">وارد شوید</a></p></section>
